public class BoundedCacheTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            BoundedCache cache = new BoundedCache(2);
            cache.put("a", "1");
            cache.put("b", "2");
            check("size after two puts", 2, cache.size());
            check("get existing key", "2", cache.get("b"));

            cache.put("c", "3");
            check("size never exceeds capacity", 2, cache.size());
            check("oldest key a was evicted", null, cache.get("a"));
            check("newest key c is present", "3", cache.get("c"));

            cache.put("b", "22");
            check("updating existing key replaces value", "22", cache.get("b"));
            check("updating existing key evicts nothing", "3", cache.get("c"));

            cache.put("d", "4");
            check("b (oldest inserted) evicted next", null, cache.get("b"));
            check("c survives the second eviction", "3", cache.get("c"));
            check("d is present", "4", cache.get("d"));

            BoundedCache tiny = new BoundedCache(1);
            tiny.put("x", "old");
            tiny.put("y", "new");
            check("capacity one keeps only latest", null, tiny.get("x"));
            check("capacity one stores newest", "new", tiny.get("y"));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

